package com.flippingfriend.companion;
/** Immutable two-leg fill measurements for one generated replacement quantity. */
final class BuyReplacementQuantityFillEvaluation {
 private final BuyReplacementQuantityFillInput source; private final double buyProbability,buyExpectedHours,buyUnitsPerHour,buyWaitHours,sellProbability,sellExpectedHours,sellUnitsPerHour,sellWaitHours;
 BuyReplacementQuantityFillEvaluation(BuyReplacementQuantityFillInput s,double bp,double bh,double bu,double bw,double sp,double sh,double su,double sw){source=s;buyProbability=bp;buyExpectedHours=bh;buyUnitsPerHour=bu;buyWaitHours=bw;sellProbability=sp;sellExpectedHours=sh;sellUnitsPerHour=su;sellWaitHours=sw;}
 int getBuyOffsetIndex(){return source.getBuyOffsetIndex();} int getSellOffsetIndex(){return source.getSellOffsetIndex();} int getBuyPrice(){return source.getBuyPrice();} int getSellPrice(){return source.getSellPrice();} int getFillableQuantity(){return source.getFillableQuantity();} double getKellyFraction(){return source.getKellyFraction();} int getSizeGridIndex(){return source.getSizeGridIndex();} double getSizeShare(){return source.getSizeShare();} int getQuantity(){return source.getQuantity();} double getExpectedProfit(){return source.getExpectedProfit();} long getWorstLoss(){return source.getWorstLoss();} double getBuyProbability(){return buyProbability;} double getBuyExpectedHours(){return buyExpectedHours;} double getBuyUnitsPerHour(){return buyUnitsPerHour;} double getBuyWaitHours(){return buyWaitHours;} double getSellProbability(){return sellProbability;} double getSellExpectedHours(){return sellExpectedHours;} double getSellUnitsPerHour(){return sellUnitsPerHour;} double getSellWaitHours(){return sellWaitHours;}
}
